library(shiny)
library(ggplot2)
library("munsell")

ui <- fluidPage(
  titlePanel("Explorer la corrélation"),

  sidebarLayout(
    sidebarPanel(

      actionButton("reset", "Reset"),

      hr(),

      h4("Statistiques"),
      textOutput("n"),
      textOutput("r"),
      textOutput("r2"),
      textOutput("eq")

    ),

    mainPanel(
      plotOutput("scatter", click = "plot_click", height = "500px")
    )
  )
)



server <- function(input, output, session){

  vals <- reactiveValues(
    data = data.frame(x = numeric(0), y = numeric(0))
  )

  observeEvent(input$plot_click, {

    vals$data <- rbind(
      vals$data,
      data.frame(
        x = input$plot_click$x,
        y = input$plot_click$y
      )
    )

  })

  observeEvent(input$reset, {
    vals$data <- data.frame(x = numeric(0), y = numeric(0))
  })

  model <- reactive({

    if(nrow(vals$data) > 2){
      lm(y ~ x, data = vals$data)
    } else {
      NULL
    }

  })

  output$scatter <- renderPlot({
    
    g <- ggplot(vals$data, aes(x, y)) +
      geom_point(size = 3) +
      xlim(-10,10) +
      ylim(-10,10) +
      theme_minimal()

    if(!is.null(model())){
      coefs <- coef(model())
      g <- g + geom_abline(intercept = coefs[1], slope =coefs[2])
    }

    g

  })

  output$n <- renderText({
    paste("n =", nrow(vals$data))
  })

  output$r <- renderText({

    if(nrow(vals$data) > 2){
      paste("r =", round(cor(vals$data$x, vals$data$y),3))
    } else {
      "r : ajouter au moins 3 points"
    }

  })

  output$r2 <- renderText({

    if(!is.null(model())){
      paste("R² =", round(summary(model())$r.squared,3))
    }

  })

  output$eq <- renderText({

    if(!is.null(model())){

      coefs <- coef(model())

      paste0(
        "y = ",
        round(coefs[1],2),
        " + ",
        round(coefs[2],2),
        "x"
      )

    }

  })

}

shinyApp(ui, server)

